class ModelConfigFactory:
    @staticmethod
    def create_config(input_config: Union[str, dict, BaseModelConfig], type: str) -> BaseModelConfig:
        """
        Creates a model config from a string, dict or BaseModelConfig
        Args:
            input_config: The config to create the model from
            type: The type of the input model
        Returns:
            A model config
        """
        if isinstance(input_config, BaseModelConfig):
            return input_config
        if isinstance(input_config, str):
            # This is purely for backwards compatibility as we used to save the model as a string
            if type == DISTILLED_MODEL:
                config = DEFAULT_STUDENT_MODELS[DEFAULT_DISTILLED_MODEL_NAME]
                config.model_name = input_config
                return config
            elif type == TEACHER_MODEL:
                if input_config not in DEFAULT_TEACHER_MODELS:
                    raise Exception("Error loading the teacher model, saved config model was saved a string but is not a default model")
                model = DEFAULT_TEACHER_MODELS[input_config]
                return model
        else:
            if input_config["provider"] == OPENAI_PROVIDER:
                return OpenAIConfig(**input_config)
            elif input_config["provider"] == LLAMA_BEDROCK_PROVIDER:
                return LlamaBedrockConfig(**input_config)
            elif input_config["provider"] == TITAN_BEDROCK_PROVIDER:
                return TitanBedrockConfig(**input_config)
            else:
                try:
                    return BaseModelConfig(**input_config)
                except:
                    raise Exception("Error loading the model config, saved config model was saved a dict but is not a valid model config")

class FunctionConfig(BaseModel):
    """
    The function config to execute the inference for the function and distillation.

    Parameters
    ----------
    distilled_model : BaseModelConfig -- the distilled model config
    current_model_stats : Dict -- the current model stats
    last_training_run : Dict -- the last training run
    current_training_run : Dict -- the current training run
    teacher_models : List[BaseModelConfig] -- the teacher models
    nr_of_training_runs : int -- the number of training runs

    """
    distilled_model: BaseModelConfig = DEFAULT_STUDENT_MODELS[DEFAULT_DISTILLED_MODEL_NAME]
    current_model_stats : Dict = {
        "trained_on_datapoints": 0,
        "running_faults": []}
    last_training_run : Dict =  {"trained_on_datapoints": 0}
    current_training_run : Dict =  {}
    teacher_models : List[BaseModelConfig] =  [DEFAULT_TEACHER_MODELS[teacher_model_name] for teacher_model_name in DEFAULT_TEACHER_MODEL_NAMES]
    nr_of_training_runs : int = 0

    def load_from_dict(self, json_dict):
        pass















    def to_dict(self):
        """
        Convert the function config to a dict
        Returns:
            The dict
        """
        try:
            config_dictionary = self.model_dump()
        except AttributeError as e:
            config_dictionary = self.dict()

        return config_dictionary
    def update_with_finetuned_response(self, response):
        """
        Update the function config with the finetuned response
        Args:
            response: The finetuned response
        """
        if response.status == "failed":
            self.current_training_run = {}
        else:
            self.distilled_model = response.fine_tuned_model
            self.last_training_run = self.current_training_run
            self.current_model_stats = {
                "trained_on_datapoints": self.current_training_run[
                    "trained_on_datapoints"],
                "running_faults": []}
            self.nr_of_training_runs += 1
            self.current_training_run = {}
